css:
.flexsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2438;
    background: linear-gradient(160deg, #fdf6f1 0%, #f6eef4 100%);
    border-radius: 18px;
}

.flexsim-container * {
    box-sizing: border-box;
}

.flexsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #5b3a78 0%, #8e4f7c 50%, #d96c4f 100%);
    color: #fdf4ee;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(91, 58, 120, 0.30);
}

.flexsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.flexsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #fcdcc9;
    background: rgba(255, 255, 255, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.flexsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #f6e4dd;
}

.flexsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b4a82;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.flexsim-period-counter #currentDay,
.flexsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #5b3a78;
}

.flexsim-round-name {
    background: #efe1f0;
    color: #5b3a78;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.flexsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b23d2a;
    background: #fbe2d8;
    padding: 4px 12px;
    border-radius: 999px;
}

.flexsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.flexsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ecdfe9;
    box-shadow: 0 4px 14px rgba(91, 58, 120, 0.06);
    border-top: 4px solid #8e4f7c;
}

.flexsim-card-bcn { border-top-color: #d96c4f; }
.flexsim-card-mun { border-top-color: #3f7e8c; }
.flexsim-card-fair { border-top-color: #b07d2a; }
.flexsim-card-budget { border-top-color: #5b3a78; }

.flexsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7a93;
}

.flexsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #5b3a78;
}

.flexsim-card-bcn .flexsim-value { color: #d96c4f; }
.flexsim-card-mun .flexsim-value { color: #3f7e8c; }
.flexsim-card-fair .flexsim-value { color: #b07d2a; }
.flexsim-card-budget .flexsim-value { color: #5b3a78; }

.flexsim-sublabel {
    font-size: 0.76rem;
    color: #9a8aa3;
    line-height: 1.35;
}

.flexsim-bcn-good .flexsim-value { color: #2e8b57; }
.flexsim-bcn-bad .flexsim-value { color: #c0392b; }
.flexsim-mun-good .flexsim-value { color: #2e8b57; }
.flexsim-fair-bad .flexsim-value { color: #c0392b; }

.flexsim-budget-over { border-top-color: #c0392b; }
.flexsim-budget-over .flexsim-value { color: #c0392b; }

.flexsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #5b3a78;
    color: #f6ecf4;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.flexsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.flexsim-budget-bar.flexsim-bar-over {
    background: #8d2c20;
}

.flexsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #d96c4f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(91, 58, 120, 0.05);
}

.flexsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.flexsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #5b3a78;
    margin-bottom: 6px;
}

.flexsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a4055;
}

.flexsim-briefing-text strong { color: #b23d2a; }
.flexsim-briefing-text em { color: #3f7e8c; font-style: italic; }

.flexsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ecdfe9;
    box-shadow: 0 4px 14px rgba(91, 58, 120, 0.06);
}

.flexsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #5b3a78;
    border-bottom: 2px solid #f1e6ef;
    padding-bottom: 8px;
}

.flexsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #4a3a5a;
    margin: 14px 0 6px;
}

.flexsim-container select,
.flexsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d9c4d4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdf8fb;
    color: #2a2438;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.flexsim-container select:focus,
.flexsim-container input[type="number"]:focus {
    outline: none;
    border-color: #8e4f7c;
    box-shadow: 0 0 0 3px rgba(142, 79, 124, 0.15);
}

.flexsim-container select option {
    background-color: #ffffff;
    color: #2a2438;
}

.flexsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #d96c4f;
}

.flexsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #8e4f7c;
    margin-top: 4px;
}

.flexsim-range-readout span:last-child {
    color: #d96c4f;
    font-weight: 800;
}

.flexsim-hint {
    font-size: 0.8rem;
    color: #9a8aa3;
    margin-top: 4px;
    line-height: 1.4;
}

.flexsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.flexsim-container .btn-primary {
    background: linear-gradient(135deg, #d96c4f 0%, #8e4f7c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(217, 108, 79, 0.28);
}

.flexsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.flexsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d9c4d4;
    color: #8a7a93;
}

.flexsim-coach {
    background: #2a2438;
    color: #f4ecf2;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(42, 36, 56, 0.22);
}

.flexsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e89a7d;
    margin-bottom: 8px;
}

.flexsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.flexsim-coach-body strong { color: #f5c08a; }
.flexsim-coach-body em { color: #97c9d2; font-style: italic; }

.flexsim-history,
.flexsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ecdfe9;
    box-shadow: 0 4px 14px rgba(91, 58, 120, 0.06);
}

.flexsim-history h3,
.flexsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #5b3a78;
}

.flexsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a3a5a;
}

.flexsim-container table#usfHistoryTable th {
    background: #f4eaf2;
    color: #5b3a78;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e6d5e3;
}

.flexsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f3ebf1;
}

.flexsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fbf6fa;
}

.flexsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .flexsim-container {
        padding: 14px;
    }
    .flexsim-header h1 {
        font-size: 1.7rem;
    }
    .flexsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .flexsim-value {
        font-size: 2rem;
    }
    .flexsim-clock {
        margin-left: 0;
    }
    .flexsim-period-counter {
        font-size: 0.88rem;
    }
    .flexsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .flexsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (flexsim) ---- */
.flexsim-completion { padding: 8px 4px 4px; }
.flexsim-cm-head { text-align: center; margin-bottom: 16px; }
.flexsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #7a4f93; }
.flexsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #a98ab8; }
.flexsim-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #2c2233; }
.flexsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.flexsim-cm-yes { background: rgba(122,79,147,0.16); color: #7a4f93; border: 1px solid rgba(122,79,147,0.5); }
.flexsim-cm-no { background: rgba(180,70,55,0.12); color: #a5412c; border: 1px solid rgba(180,70,55,0.45); }
.flexsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.flexsim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(122,79,147,0.08); border: 1px solid rgba(122,79,147,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.flexsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #7a4f93; }
.flexsim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #656b7c; text-transform: uppercase; letter-spacing: 0.03em; }
.flexsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #2c2233; }
.flexsim-cm-insights { margin: 0; padding-left: 20px; }
.flexsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #363c4b; }

