(function() {
    'use strict';

    class FlexEffectAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Flex Effect`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // NUMBERS REFERENCE CARD (in € thousands for budget).
            this.BUDGET_CAP = 1200;          // €1.2M shared, fixed.
            this.BOTH_FIRST_CHOICE = 1950;   // funding both dream policies ≈ €1.95M.

            // Meter starting points (kept LOW with headroom — no early saturation).
            this.START_BCN = 25;             // Barcelona Retention (turnover-intention reversed).
            this.START_MUN = 61;             // Munich Engagement (vs 74 target).
            this.START_FAIR = 40;            // Eligibility Fairness for the ~40% who can't flex.

            this.MUN_TARGET = 74;            // engagement target.

            // Concept-correct play (NOT the seeded defaults).
            this.TRUE_BCN_NEED = `conflict`;     // Barcelona: remove work-family conflict.
            this.TRUE_MUN_NEED = `enrichment`;   // Munich: create work-family enrichment.
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    bcn: this.START_BCN,
                    mun: this.START_MUN,
                    fair: this.START_FAIR,
                    budgetUsed: 0,
                    overBudget: false,
                    rtoMandate: false,
                    bcnHistory: [this.START_BCN],
                    munHistory: [this.START_MUN],
                    fairHistory: [this.START_FAIR],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed MIDDLING / NEUTRAL — a click-through must NOT auto-win.
                state.decisions = {
                    bcnNeed: `enrichment`,   // plausible but wrong for Barcelona (it needs conflict-reduction).
                    munNeed: `conflict`,     // plausible but wrong for Munich (it needs enrichment).
                    diag: 50,
                    bcnPolicy: `fourday`,    // the high-appeal trap, not the evidenced hybrid.
                    munPolicy: `same`,       // one-size-fits-all, the classic error.
                    eligibility: `blanket`,  // no fairness principle.
                    invest: 60,
                    capability: `memo`,      // cheap, under-funds capability.
                    grievance: `token`,      // buy them off, no procedural justice.
                    coverage: `rollback`,    // scraps the benefit instead of protecting service.
                    protect: 50,
                    metric: `turnover`,      // lagging only.
                    checkpoint: `annual`,
                    defend: `spin`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const bn = document.getElementById(`bcnNeedInput`);
                const mn = document.getElementById(`munNeedInput`);
                const dg = document.getElementById(`diagInput`);
                if (bn) decisions.bcnNeed = bn.value;
                if (mn) decisions.munNeed = mn.value;
                if (dg) decisions.diag = parseInt(dg.value, 10);
                if (!Number.isFinite(decisions.diag) || decisions.diag < 0 || decisions.diag > 100) {
                    warn(`warn_diag_range`); return false;
                }
            } else if (round === 2) {
                const bp = document.getElementById(`bcnPolicyInput`);
                const mp = document.getElementById(`munPolicyInput`);
                const el = document.getElementById(`eligibilityInput`);
                const inv = document.getElementById(`investInput`);
                if (bp) decisions.bcnPolicy = bp.value;
                if (mp) decisions.munPolicy = mp.value;
                if (el) decisions.eligibility = el.value;
                if (inv) decisions.invest = parseInt(inv.value, 10);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0 || decisions.invest > 400) {
                    warn(`warn_invest_range`); return false;
                }
            } else if (round === 3) {
                const cp = document.getElementById(`capabilityInput`);
                const gr = document.getElementById(`grievanceInput`);
                const cv = document.getElementById(`coverageInput`);
                const pr = document.getElementById(`protectInput`);
                if (cp) decisions.capability = cp.value;
                if (gr) decisions.grievance = gr.value;
                if (cv) decisions.coverage = cv.value;
                if (pr) decisions.protect = parseInt(pr.value, 10);
                if (!Number.isFinite(decisions.protect) || decisions.protect < 0 || decisions.protect > 100) {
                    warn(`warn_protect_range`); return false;
                }
            } else if (round === 4) {
                const me = document.getElementById(`metricInput`);
                const ck = document.getElementById(`checkpointInput`);
                const df = document.getElementById(`defendInput`);
                const co = document.getElementById(`convictionInput`);
                if (me) decisions.metric = me.value;
                if (ck) decisions.checkpoint = ck.value;
                if (df) decisions.defend = df.value;
                if (co) decisions.conviction = parseInt(co.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let bcnDelta = 0, munDelta = 0, fairDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // R1 — Diagnose the two cultures (conflict vs enrichment).
                // Barcelona's problem IS work-family conflict (rigidity + commuting drive exits).
                if (d.bcnNeed === `conflict`) { bcnDelta += 10; coachKey = `coach_r1_bcn_right`; }
                else if (d.bcnNeed === `enrichment`) { bcnDelta += 2; coachKey = `coach_r1_bcn_enrich`; }
                else if (d.bcnNeed === `pay`) { bcnDelta -= 6; coachKey = `coach_r1_bcn_pay`; }
                else { bcnDelta -= 10; coachKey = `coach_r1_bcn_nothing`; } // 'nothing structural'.

                // Munich's problem is disengagement → needs ENRICHMENT, not friction-removal.
                if (d.munNeed === `enrichment`) { munDelta += 7; }
                else if (d.munNeed === `conflict`) { munDelta -= 4; coachKey = `coach_r1_mun_conflict`; }
                else if (d.munNeed === `turnover`) { munDelta -= 5; coachKey = `coach_r1_mun_turnover`; }
                else { munDelta -= 7; coachKey = `coach_r1_mun_nothing`; } // leave Munich out.

                // Diagnostic sharpness: separating conflict from enrichment.
                if (d.diag >= 70) { bcnDelta += 5; munDelta += 5; fairDelta += 3; }
                else if (d.diag <= 25) { bcnDelta -= 4; munDelta -= 4; coachKey = `coach_r1_blunt`; }

                if (d.bcnNeed === this.TRUE_BCN_NEED && d.munNeed === this.TRUE_MUN_NEED) {
                    if (d.diag >= 70) coachKey = `coach_r1_sharp`;
                    summaryKey = `sum_r1_good`;
                } else {
                    summaryKey = `sum_r1_weak`;
                }
            } else if (round === 2) {
                // R2 — Choose the policy, set eligibility, allocate the shared €1.2M.
                // Barcelona: structured hybrid has the strongest work-family enrichment evidence.
                switch (d.bcnPolicy) {
                    case `hybrid`:   spend += 520; bcnDelta += 16; coachKey = `coach_r2_bcn_hybrid`; break;
                    case `fourday`:  spend += 600; bcnDelta += 6;  fairDelta -= 6; coachKey = `coach_r2_fourday`; break; // appeal, but coverage damage.
                    case `flextime`: spend += 220; bcnDelta += 7;  coachKey = `coach_r2_bcn_flex`; break;
                }

                // Munich: light flextime / outcome-based autonomy fits self-managing consultants.
                switch (d.munPolicy) {
                    case `flextime`: spend += 200; munDelta += 6;  coachKey = (d.bcnPolicy === `hybrid`) ? `coach_r2_fit` : coachKey; break;
                    case `hybrid`:   spend += 480; munDelta -= 4;  coachKey = `coach_r2_mun_hybrid`; break; // process onto self-managers.
                    case `fourday`:  spend += 560; munDelta -= 6;  fairDelta -= 4; coachKey = `coach_r2_mun_fourday`; break; // collides with client-site.
                    case `same`:     spend += 520; munDelta -= 8;  coachKey = `coach_r2_onesize`; break; // one-size-fits-all error.
                }

                // Eligibility rule for the ~40% who cannot flex — procedural justice.
                switch (d.eligibility) {
                    case `principle`: spend += 40; fairDelta += 18; bcnDelta += 2; munDelta += 2; break;
                    case `blanket`:   fairDelta -= 8;  coachKey = `coach_r2_blanket`; break;
                    case `everyone`:  fairDelta -= 4;  bcnDelta -= 3; munDelta -= 3; coachKey = `coach_r2_everyone`; break; // ignores coverage needs.
                }

                // Manager-training & norms investment now (prevents the R3 capability shock).
                spend += d.invest;
                if (d.invest >= 90) { munDelta += 2; fairDelta += 2; }
                else if (d.invest <= 20) { munDelta -= 4; coachKey = `coach_r2_underinvest`; }

                summaryKey = (d.bcnPolicy === `hybrid` && d.munPolicy === `flextime` && d.eligibility === `principle`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // R3 — Manager capability & the fairness backlash.
                const underTrained = (d.invest || 0) < 60; // R2 under-investment resurfaces here.

                // Munich managers can't lead flexible client-site teams.
                switch (d.capability) {
                    case `coach`:  spend += 90; munDelta += 5; fairDelta += 3; coachKey = `coach_r3_coach`; break;
                    case `memo`:   spend += 10; munDelta += (underTrained ? -3 : 2); coachKey = `coach_r3_memo`; break;
                    case `ignore`: munDelta += (underTrained ? -10 : -5); coachKey = `coach_r3_ignore`; break;
                }

                // 24/7-support fairness grievance — procedural justice over a token bonus.
                switch (d.grievance) {
                    case `justice`: spend += 30; fairDelta += 14; bcnDelta += 3; break;
                    case `token`:   spend += 40; fairDelta -= 2; coachKey = `coach_r3_token`; break;
                    case `dismiss`: fairDelta -= 14; bcnDelta -= 4; coachKey = `coach_r3_dismiss`; break;
                }

                // Customer lost Friday coverage — protect service without scrapping the benefit.
                switch (d.coverage) {
                    case `rota`:     spend += 35; bcnDelta += 6; munDelta += 2; coachKey = (d.grievance === `justice`) ? `coach_r3_intact` : coachKey; break;
                    case `rollback`: bcnDelta -= 10; fairDelta -= 4; coachKey = `coach_r3_rollback`; break; // scraps the popular benefit.
                    case `nothing`:  bcnDelta -= 5; munDelta -= 4; coachKey = `coach_r3_nothing`; break;
                }

                // Protecting non-eligible roles from feeling second-class.
                if (d.protect >= 65) { fairDelta += 7; }
                else if (d.protect <= 25) { fairDelta -= 8; coachKey = `coach_r3_unprotected`; }

                summaryKey = (d.capability === `coach` && d.grievance === `justice` && d.coverage === `rota`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // R4 — Measure & defend to the CEO (avert the return-to-office mandate).
                switch (d.metric) {
                    case `leading`:  bcnDelta += 8; munDelta += 3; fairDelta += 4; coachKey = `coach_r4_leading`; break;
                    case `turnover`: bcnDelta += 1; coachKey = `coach_r4_lagging`; break;
                    case `cost`:     bcnDelta -= 3; munDelta -= 3; coachKey = `coach_r4_cost`; break;
                }

                switch (d.checkpoint) {
                    case `twoq`:   bcnDelta += 6; munDelta += 2; break;
                    case `annual`: bcnDelta -= 3; coachKey = `coach_r4_annual`; break;
                    case `none`:   bcnDelta -= 6; munDelta -= 4; coachKey = `coach_r4_nocheck`; break;
                }

                switch (d.defend) {
                    case `honest`:  bcnDelta += 9; munDelta += 3; fairDelta += 4; coachKey = (d.metric === `leading`) ? `coach_r4_honest` : coachKey; break;
                    case `spin`:    bcnDelta -= 6; coachKey = `coach_r4_spin`; break;
                    case `uniform`: { // conceding the return-to-office mandate is the worst outcome.
                        bcnDelta -= 16; munDelta -= 12; fairDelta -= 8; ds.rtoMandate = true; coachKey = `coach_r4_uniform`; break;
                    }
                }

                // Conviction in leading indicators over a convenient number.
                bcnDelta += Math.round((d.conviction - 60) / 12);
                munDelta += Math.round((d.conviction - 60) / 20);

                summaryKey = (d.metric === `leading` && d.checkpoint === `twoq` && d.defend === `honest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Budget accounting — the single shared €1.2M cap. Overspend is penalised hard.
            const prevUsed = ds.budgetUsed;
            ds.budgetUsed = prevUsed + spend;
            if (ds.budgetUsed > this.BUDGET_CAP) {
                ds.overBudget = true;
                const over = ds.budgetUsed - this.BUDGET_CAP;
                // Overspend past the shared cap punishes all three meters (CEO won't fund a blank cheque).
                const penalty = Math.min(28, Math.round(over / 25));
                bcnDelta -= penalty;
                munDelta -= Math.round(penalty * 0.7);
                fairDelta -= Math.round(penalty * 0.5);
                if (coachKey === `coach_default` || summaryKey === `sum_default`) coachKey = `coach_overbudget`;
                summaryKey = `sum_overbudget`;
            }

            ds.bcn = Math.max(0, Math.min(100, ds.bcn + bcnDelta));
            ds.mun = Math.max(0, Math.min(100, ds.mun + munDelta));
            ds.fair = Math.max(0, Math.min(100, ds.fair + fairDelta));

            ds.bcnHistory.push(Math.round(ds.bcn));
            ds.munHistory.push(Math.round(ds.mun));
            ds.fairHistory.push(Math.round(ds.fair));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                bcn: Math.round(ds.bcn),
                bcnDelta: Math.round(bcnDelta),
                mun: Math.round(ds.mun),
                munDelta: Math.round(munDelta),
                fair: Math.round(ds.fair),
                fairDelta: Math.round(fairDelta),
                budgetUsed: Math.round(ds.budgetUsed),
                overBudget: ds.overBudget,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoneyK(valueK) {
            // valueK is in € thousands. Locale-aware: € before in EN, after in ES (comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const millions = valueK / 1000;
            // Show as millions with one decimal when >= 1000k, else as €Nk.
            if (Math.abs(valueK) >= 1000) {
                const m = Math.round(millions * 10) / 10;
                if (lang === `es`) {
                    return `${m.toString().replace(`.`, `,`)} M€`;
                }
                return `€${m}M`;
            }
            const k = Math.round(valueK);
            if (lang === `es`) {
                return `${k} k€`;
            }
            return `€${k}k`;
        }

