        _composite(ds) {
            const bcn = Math.round(ds.bcn);
            const mun = Math.round(ds.mun);
            const fair = Math.round(ds.fair);
            const onBudget = !ds.overBudget && ds.budgetUsed <= this.BUDGET_CAP;
            let composite = Math.round(bcn * 0.34 + mun * 0.30 + fair * 0.26 + (onBudget ? 10 : 0));
            if (ds.rtoMandate) composite = Math.round(composite * 0.6);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const bcn = Math.round(ds.bcn);
            const mun = Math.round(ds.mun);
            const fair = Math.round(ds.fair);
            const t = window.mySimulation.t.bind(window.mySimulation);

            const munHit = mun >= this.MUN_TARGET;
            const bcnStrong = bcn >= 60;
            const fairStrong = fair >= 60;
            const onBudget = !ds.overBudget && ds.budgetUsed <= this.BUDGET_CAP;
            // Composite: all four KPIs matter; budget is a gate-multiplier, RTO mandate is fatal.
            const composite = this._composite(ds);

            let performance = window.mySimulation.t(`grade_rto`);
            if (!ds.rtoMandate) {
                if (bcnStrong && munHit && fairStrong && onBudget && composite >= 78) performance = window.mySimulation.t(`grade_win`);
                else if (bcnStrong && munHit && onBudget) performance = window.mySimulation.t(`grade_fix`);
                else if (bcnStrong && onBudget) performance = window.mySimulation.t(`grade_bcnsaved`);
                else if (!onBudget) performance = window.mySimulation.t(`grade_overbudget`);
                else performance = window.mySimulation.t(`grade_thin`);
            }

            const insights = [];
            if (ds.rtoMandate) insights.push(t(`insight_rto`));
            else if (bcnStrong && munHit && fairStrong && onBudget) insights.push(t(`insight_win`));
            else if (bcnStrong && munHit) insights.push(t(`insight_fix`));
            else insights.push(t(`insight_short`));

            if (mun < this.MUN_TARGET) insights.push(t(`insight_munlow`));
            if (fair < 45) insights.push(t(`insight_fairlow`));
            if (!onBudget) insights.push(t(`insight_overbudget`));
            if (bcnStrong && munHit && fairStrong && onBudget) insights.push(t(`insight_enrichment`));

            return {
                bcn: bcn,
                mun: mun,
                fair: fair,
                budgetUsed: Math.round(ds.budgetUsed),
                onBudget: onBudget,
                munHit: munHit,
                rtoMandate: ds.rtoMandate,
                met: (!ds.rtoMandate && bcnStrong && munHit && fairStrong && onBudget),
                overBudget: !onBudget,
                munLow: !munHit,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="flexsim-cm-badge flexsim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="flexsim-cm-badge flexsim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.rtoMandate) failBadge += ` <span class="flexsim-cm-badge flexsim-cm-no">` + T(`cm_rto`) + `</span>`;
            if (s.overBudget) failBadge += ` <span class="flexsim-cm-badge flexsim-cm-no">` + T(`cm_overbudget`) + `</span>`;
            if (s.munLow) failBadge += ` <span class="flexsim-cm-badge flexsim-cm-no">` + T(`cm_munlow`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="flexsim-cm-metric"><span class="flexsim-cm-mv">` + Math.round(s.bcn || 0) + `</span><span class="flexsim-cm-ml">` + T(`cm_m_bcn`) + `</span></div>`
                + `<div class="flexsim-cm-metric"><span class="flexsim-cm-mv">` + Math.round(s.mun || 0) + `</span><span class="flexsim-cm-ml">` + T(`cm_m_mun`) + `</span></div>`
                + `<div class="flexsim-cm-metric"><span class="flexsim-cm-mv">` + Math.round(s.fair || 0) + `</span><span class="flexsim-cm-ml">` + T(`cm_m_fair`) + `</span></div>`
                + `<div class="flexsim-cm-metric"><span class="flexsim-cm-mv">` + (`€` + Math.round(s.budgetUsed || 0) + `k`) + `</span><span class="flexsim-cm-ml">` + T(`cm_m_budget`) + `</span></div>`;
            return ``
                + `<div class="flexsim-completion">`
                +   `<div class="flexsim-cm-head">`
                +     `<div class="flexsim-cm-score">` + score + `<span class="flexsim-cm-score-max">/100</span></div>`
                +     `<div class="flexsim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="flexsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="flexsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="flexsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            const t = window.mySimulation.t.bind(window.mySimulation);
            if (ds.rtoMandate) return t(`hint_rto`);
            if (ds.overBudget) return t(`hint_budget`);
            if (state.currentPeriod >= 2 && ds.fair < 35) return t(`hint_fairness`);
            if (state.currentPeriod >= 2 && ds.mun < 58) return t(`hint_munich`);
            if (state.currentPeriod >= 3 && ds.bcn < 45) return t(`hint_barcelona`);
            if (ds.bcn >= 60 && ds.mun >= this.MUN_TARGET && ds.fair >= 60) return t(`hint_strong`);
            return null;
        }

